#!/usr/bin/env python3
"""Patch the Android project generated by `flutter create` (runs in CI only)."""
import pathlib
import re
import sys

APP = pathlib.Path("android/app")


def fail(msg: str) -> None:
    print(f"PATCH ERROR: {msg}")
    sys.exit(1)


# ---------- 1) release signing ----------
kts = APP / "build.gradle.kts"
groovy = APP / "build.gradle"

if kts.exists():
    s = kts.read_text(encoding="utf-8")
    signing = (
        "    signingConfigs {\n"
        '        create("release") {\n'
        '            storeFile = file(System.getenv("KEYSTORE_PATH") ?: "missing.jks")\n'
        '            storePassword = System.getenv("KEYSTORE_PASSWORD")\n'
        '            keyAlias = System.getenv("KEY_ALIAS")\n'
        '            keyPassword = System.getenv("KEY_PASSWORD")\n'
        "        }\n"
        "    }\n\n"
    )
    if "    buildTypes {" not in s:
        fail("buildTypes block not found in build.gradle.kts")
    s = s.replace("    buildTypes {", signing + "    buildTypes {", 1)
    new = s.replace('signingConfigs.getByName("debug")', 'signingConfigs.getByName("release")')
    if new == s:
        fail("debug signing line not found in build.gradle.kts")
    kts.write_text(new, encoding="utf-8")
elif groovy.exists():
    s = groovy.read_text(encoding="utf-8")
    signing = (
        "    signingConfigs {\n"
        "        release {\n"
        '            storeFile file(System.getenv("KEYSTORE_PATH") ?: "missing.jks")\n'
        '            storePassword System.getenv("KEYSTORE_PASSWORD")\n'
        '            keyAlias System.getenv("KEY_ALIAS")\n'
        '            keyPassword System.getenv("KEY_PASSWORD")\n'
        "        }\n"
        "    }\n\n"
    )
    if "    buildTypes {" not in s:
        fail("buildTypes block not found in build.gradle")
    s = s.replace("    buildTypes {", signing + "    buildTypes {", 1)
    new = s.replace("signingConfigs.debug", "signingConfigs.release")
    if new == s:
        fail("debug signing line not found in build.gradle")
    groovy.write_text(new, encoding="utf-8")
else:
    fail("no android/app/build.gradle(.kts) found")

# ---------- 2) manifest: internet, https queries, app label ----------
manifest = APP / "src/main/AndroidManifest.xml"
if not manifest.exists():
    fail("AndroidManifest.xml not found")
m = manifest.read_text(encoding="utf-8")

if "android.permission.INTERNET" not in m:
    m = m.replace(
        "<application",
        '<uses-permission android:name="android.permission.INTERNET"/>\n    <application',
        1,
    )

if "android.permission.REQUEST_INSTALL_PACKAGES" not in m:
    m = m.replace(
        "<application",
        '<uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES"/>\n    <application',
        1,
    )

if "<queries>" not in m:
    queries = (
        "<queries>\n"
        "        <intent>\n"
        '            <action android:name="android.intent.action.VIEW"/>\n'
        '            <data android:scheme="https"/>\n'
        "        </intent>\n"
        "    </queries>\n    "
    )
    m = m.replace("<application", queries + "<application", 1)

m, n = re.subn(r'android:label="[^"]*"', 'android:label="لمّتنا"', m, count=1)
if n != 1:
    fail("android:label not found in manifest")

manifest.write_text(m, encoding="utf-8")
print("Android project patched OK")
